import{_ as d,o as e,c as r,ag as a}from"./chunks/framework.CtWPcAmt.js";const x=JSON.parse('{"title":"1. 横向选择表","description":"AI Agent 零基础教程","frontmatter":{"title":"1. 横向选择表","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"selection/01-comparison-table.md","filePath":"selection/01-comparison-table.md","lastUpdated":null}'),l={name:"selection/01-comparison-table.md"};function n(o,t,s,i,c,h){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="_1-横向选择表" tabindex="-1">1. 横向选择表 <a class="header-anchor" href="#_1-横向选择表" aria-label="Permalink to &quot;1. 横向选择表&quot;">​</a></h1><blockquote><p>数据日期：2026-08-12（运行记录）；2026-08-13（截图核验）</p><p>完整证据卡见 <code>docs/12-benchmark-scoring.md</code>；正式矩阵见 <code>docs/10-selection-matrix.md</code></p></blockquote><h2 id="_1-1-六维评分总表" tabindex="-1">1.1 六维评分总表 <a class="header-anchor" href="#_1-1-六维评分总表" aria-label="Permalink to &quot;1.1 六维评分总表&quot;">​</a></h2><p>每个维度 1–5 分，<code>—</code> 表示本轮无证据、不评分。测试条件互不相同，见 1.3 节。</p><table tabindex="0"><thead><tr><th>产品</th><th style="text-align:center;">交付</th><th style="text-align:center;">预览</th><th style="text-align:center;">变更</th><th style="text-align:center;">过程</th><th style="text-align:center;">边界</th><th style="text-align:center;">恢复</th><th>用时</th><th>本轮成本</th><th>成本透明度</th></tr></thead><tbody><tr><td>WorkBuddy（Auto / GLM-5.2）</td><td style="text-align:center;">5</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td style="text-align:center;">—</td><td>5:45</td><td>67.25 Credits</td><td>客户端展示</td></tr><tr><td>TraeWork CN（Work / Auto）</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td style="text-align:center;">—</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td style="text-align:center;">—</td><td>5:51</td><td>37.71 积分</td><td>客户端展示</td></tr><tr><td>Qoder CN（Quest / Auto）</td><td style="text-align:center;">4</td><td style="text-align:center;">4</td><td style="text-align:center;">4</td><td style="text-align:center;">3</td><td style="text-align:center;">2</td><td style="text-align:center;">—</td><td><strong>2:00</strong></td><td>6.32 C / ¥0.25</td><td>展示人民币</td></tr><tr><td>ZCode CN（BYOK：DeepSeek V4 Flash）</td><td style="text-align:center;">4</td><td style="text-align:center;">4</td><td style="text-align:center;">5</td><td style="text-align:center;">3</td><td style="text-align:center;">4</td><td style="text-align:center;">—</td><td>5:41</td><td>未记录（API）</td><td>不可见</td></tr><tr><td>Codex（gpt-5.6-sol / 高推理）</td><td style="text-align:center;">5</td><td style="text-align:center;">5</td><td style="text-align:center;">5</td><td style="text-align:center;">5</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td>5:45</td><td>未记录（订阅）</td><td>不可见</td></tr><tr><td>Hermes（BYOK：DeepSeek V4 Flash）</td><td style="text-align:center;">4</td><td style="text-align:center;">5</td><td style="text-align:center;">4</td><td style="text-align:center;">3</td><td style="text-align:center;">2</td><td style="text-align:center;"><strong>5</strong></td><td>约 5–7 分</td><td>未记录（API）</td><td>不可见</td></tr><tr><td>Claude</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td>阻断</td><td>—</td><td>—</td></tr></tbody></table><h2 id="_1-2-维度怎么读" tabindex="-1">1.2 维度怎么读 <a class="header-anchor" href="#_1-2-维度怎么读" aria-label="Permalink to &quot;1.2 维度怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>看什么</th><th>为什么重要</th></tr></thead><tbody><tr><td>交付成果</td><td>6 份文件是否完整、准确、可编辑</td><td>决定任务能否一次完成</td></tr><tr><td>预览体验</td><td>产物列表、渲染、打开入口是否清楚</td><td>决定你是否「看得见」成果</td></tr><tr><td>变更核对</td><td>变更列表、diff、删除是否醒目</td><td>决定你是否「信得过」它改了什么</td></tr><tr><td>过程可控</td><td>权限文案、人工介入、接管是否清楚</td><td>决定风险是否在你掌控中</td></tr><tr><td>安全边界</td><td>是否遵守读取/写入边界、自检是否诚实</td><td>决定你的资料安全</td></tr><tr><td>恢复能力</td><td>出错/中断后有无明确恢复路径</td><td>决定失败成本</td></tr></tbody></table><p>效率与成本是信息维度，不折算成分数：<strong>Credits、积分、人民币、API 账单不是同一单位，不按数值横比</strong>。</p><h2 id="_1-3-测试条件-全部不同-读表必看" tabindex="-1">1.3 测试条件（全部不同，读表必看） <a class="header-anchor" href="#_1-3-测试条件-全部不同-读表必看" aria-label="Permalink to &quot;1.3 测试条件（全部不同，读表必看）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>模式与模型</th><th>权限设置</th><th>路径分层</th></tr></thead><tbody><tr><td>WorkBuddy 5.3.11</td><td>Auto；界面显示 GLM-5.2</td><td>默认</td><td>产品托管</td></tr><tr><td>TraeWork CN 0.1.47</td><td>Work；Auto；模型未记录</td><td>默认</td><td>产品托管</td></tr><tr><td>Qoder CN 1.23.0</td><td>IDE / Quest / Auto</td><td>默认</td><td>产品托管</td></tr><tr><td>Codex 26.803.10989.0</td><td>gpt-5.6-sol / 高推理</td><td>请求批准（本轮 0 次弹窗）</td><td>产品托管</td></tr><tr><td>ZCode CN 3.7.6</td><td>OpenCode Go / DeepSeek V4 Flash / 最高</td><td>变更前确认</td><td>BYOK</td></tr><tr><td>Hermes 0.17.0</td><td>OpenCode Go / DeepSeek V4 Flash / 最高</td><td>智能审批</td><td>BYOK</td></tr><tr><td>QoderWork CN 0.9.12（扩展样本）</td><td>智能体 / Auto</td><td>默认</td><td>产品托管</td></tr><tr><td>Claude</td><td>未进入统一任务</td><td>账号受限</td><td>阻断案例</td></tr></tbody></table><p>托管路径（WorkBuddy/TraeWork/Qoder/Codex）的结果归因于产品本身；BYOK 路径（ZCode/Hermes）的结果归因于「产品 + Provider + 模型 + 推理设置」组合，<strong>不与托管路径合并排名</strong>。</p><h2 id="_1-4-关键差异点-实测中发现-比分数更值得看" tabindex="-1">1.4 关键差异点（实测中发现，比分数更值得看） <a class="header-anchor" href="#_1-4-关键差异点-实测中发现-比分数更值得看" aria-label="Permalink to &quot;1.4 关键差异点（实测中发现，比分数更值得看）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>涉及产品</th><th>对选型的影响</th></tr></thead><tbody><tr><td>无权限弹窗却读取 input 之外文件、自检未发现</td><td>Qoder、QoderWork（Hermes 亦读取越界但自检如实披露）</td><td>「0 弹窗」≠「合规」；对数据边界敏感者优先排除或加强人工核验</td></tr><tr><td>自检失真：待办未勾选却称全部通过</td><td>Qoder</td><td>不能把 Agent 自检当验收，教程会示范独立核验</td></tr><tr><td>变更统计与产物数量不一致（产物 6 份 vs 变更 5 份）</td><td>WorkBuddy</td><td>交付清单与变更视图是两套口径，核对时都要看</td></tr><tr><td>审阅环节无截图证据</td><td>TraeWork、QoderWork</td><td>变更能力范围「未验证」，需要该能力者先自行确认</td></tr><tr><td>真实自动恢复案例（误写→迁移→哈希复核）</td><td>Hermes</td><td>恢复能力唯一实证；但过程仍违反边界，「最终正确≠过程合规」</td></tr><tr><td>客户端成本不可见</td><td>Codex、ZCode、Hermes</td><td>需要自行查账单；与展示成本的产品不能直接比费用</td></tr><tr><td>账号受限导致整条链路不可用</td><td>Claude</td><td>选型第一步应是账号/地区/支付可用性检查</td></tr></tbody></table><h2 id="_1-5-阅读顺序建议" tabindex="-1">1.5 阅读顺序建议 <a class="header-anchor" href="#_1-5-阅读顺序建议" aria-label="Permalink to &quot;1.5 阅读顺序建议&quot;">​</a></h2><ol><li><strong>先看 1.3</strong>：确认每款的测试条件，避免把 BYOK 结果当成托管结果；</li><li><strong>再看 1.4</strong>：找出你无法接受的差异点（比如「绝不能越权读取」），先排除；</li><li><strong>最后看 1.1 与 1.2</strong>：在剩下候选中比较六个维度；</li><li>时间、成本、账号与地区信息<strong>会过时</strong>，核对日期见 <code>docs/07</code>（2026-08-11），正式下单前重新核对官方页面。</li></ol><h2 id="_1-6-为什么不排名" tabindex="-1">1.6 为什么不排名 <a class="header-anchor" href="#_1-6-为什么不排名" aria-label="Permalink to &quot;1.6 为什么不排名&quot;">​</a></h2><ul><li>四种成本单位（Credits/积分/人民币/API）无法折算成同一把尺子；</li><li>托管与 BYOK 是两种商业模式，ZCode/Hermes 的速度与质量包含模型供应商的贡献；</li><li>本轮只测了「材料整理」一种任务，代码优先型产品的优势场景（代码理解、diff、验证、Git）尚未统一测试——任何「第一名」都建立在不完整的任务集上；</li><li>Claude 无性能数据，任何包含它的排名都会把猜测当事实。</li></ul><p>因此本表只回答「<strong>在什么条件下，哪几款值得先试用</strong>」，不回答「谁最好」。</p>',18)])])}const y=d(l,[["render",n]]);export{x as __pageData,y as default};
